:root {
  font-family: var(--vscode-font-family);
  /*
   * The conversation is read like code, so it never renders below the editor. Proportional text needs to
   * be a step larger than monospace to read the same size beside it. The var() fallbacks keep the whole
   * declaration valid: an undefined custom property inside max() would drop it and take the floor with it.
   * kiwiAgent.fontSize overrides the result.
   */
  font-size: calc(max(var(--vscode-font-size, 13px), var(--vscode-editor-font-size, 14px)) + 1px);
  color: var(--vscode-foreground);
}

body {
  margin: 0;
  height: 100vh;
}

[hidden] {
  display: none !important;
}

/* A custom element is inline by default, and block markdown holds paragraphs and lists. */
markdown-text[block] {
  display: block;
}

chat-app {
  display: flex;
  flex-direction: column;
  height: 100vh;

  & > .chats,
  & > .new-session {
    flex: 1;
    min-height: 0;
  }

  /*
   * One row: the flow as steps, the current one lit, and at the right the one
   * next thing. The lit step is the stage; nothing restates it. Its own
   * background sets it apart from the plan tabs below, so the two rows read
   * as two different things.
   */
  & > .plan-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.3rem 0.5rem;
    padding: 0.35rem 0.6rem;
    margin-bottom: 0.4rem;    background: var(--vscode-sideBarSectionHeader-background, var(--vscode-editorWidget-background));

    & .steps {
      display: inline-flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0 0.1rem;
      margin-right: auto;
    }

    /* Stages in order, read left to right: a chevron between each, the passed ones plain, the one at hand lit, the rest dim. */
    & .step {
      background: none;
      border: none;
      border-radius: 0;
      color: var(--vscode-disabledForeground);
      padding: 0.1rem 0.3rem;
      white-space: nowrap;

      & + .step::before {
        content: '›';
        margin-right: 0.45rem;
        color: var(--vscode-descriptionForeground);
        font-weight: 400;
      }

      &.done,
      &.reached {
        color: var(--vscode-foreground);
      }

      &.current {
        font-weight: 600;
        color: var(--vscode-focusBorder);
      }

      /* The step whose conversation the chat shows. */
      &.selected {
        text-decoration: underline;
        text-underline-offset: 0.3em;
      }

      /* Its conversation moved while another step's was shown. */
      &.moved:not(.current)::after {
        content: ' •';
        color: var(--vscode-foreground);
      }

      /* The flow stands still until the person acts: warm, with a dot, so it reads apart from a step at work. */
      &.current.yours {
        color: var(--vscode-notificationsWarningIcon-foreground, var(--vscode-editorWarning-foreground));

        &::after {
          content: '';
          display: inline-block;
          width: 0.4rem;
          height: 0.4rem;
          margin-left: 0.3rem;
          vertical-align: middle;
          border-radius: 50%;
          background: currentColor;
        }
      }

      &:is(button):hover {
        text-decoration: underline;
        cursor: pointer;
      }
    }

    & .running {
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      font-family: var(--vscode-editor-font-family);
      animation: pulse 1.2s ease-in-out infinite;
    }

    /* An outcome is read in full: it wraps onto its own lines rather than being cut at the panel's edge. */
    & .ran {
      opacity: 0.75;
      min-width: 0;
      overflow-wrap: anywhere;

      &.failed {
        opacity: 1;
        color: var(--vscode-errorForeground);
      }
    }

    & .stop {
      background: var(--vscode-button-secondaryBackground);
      color: var(--vscode-button-secondaryForeground);
    }

    & .repair {
      background: var(--vscode-inputValidation-warningBackground);
      color: inherit;
      border: 1px solid var(--vscode-inputValidation-warningBorder);
    }

    /* The one next step: a button when it moves the plan on, green when it is the gate; a link when the act is on a row; text while someone else works. */
    & .next {
      white-space: nowrap;

      &.approve,
      &.implement {
        background: var(--vscode-testing-iconPassed);
        color: var(--vscode-button-foreground);
      }

      /* A goto is always the person's act: a pill, not a faint link, so it is not read past. */
      &.goto {
        background: var(--vscode-button-secondaryBackground);
        color: var(--vscode-button-secondaryForeground);

        &:hover {
          background: var(--vscode-button-secondaryHoverBackground, var(--vscode-button-secondaryBackground));
        }

        /* A run stopped mid-turn on the person: nothing moves until it is answered. */
        &.blocked {
          background: var(--vscode-inputValidation-warningBackground);
          color: inherit;
          border: 1px solid var(--vscode-inputValidation-warningBorder);
          animation: pulse 1.2s ease-in-out infinite;
        }
      }

      &.waiting,
      &.done {
        opacity: 0.75;
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
      }

      &.done {
        color: var(--vscode-testing-iconPassed);
        opacity: 1;
      }
    }
  }

  /* The plan's tabs and the chat as one strip: what the session has to show, each counted when it needs the reader. */
  & > .plan-tabs {
    display: flex;
    flex-wrap: wrap;
    gap: 0.2rem;
    padding: 0 0.6rem;
    border-bottom: 1px solid var(--vscode-panel-border);
    & .tab {
      background: none;
      color: inherit;
      opacity: 0.7;
      border-bottom: 2px solid transparent;
      border-radius: 0;
      padding: 0.25rem 0.6rem;

      &:hover {
        opacity: 1;
        background: var(--vscode-list-hoverBackground);
      }

      &.active {
        opacity: 1;
        border-bottom-color: var(--vscode-focusBorder);
      }

      /* The conversation moved on while another tab was open; the person's next act is on an attention tab. */
      &.moved,
      &.attention {
        opacity: 1;

        &::after {
          content: '';
          display: inline-block;
          width: 0.4rem;
          height: 0.4rem;
          margin-left: 0.35rem;
          vertical-align: middle;
          border-radius: 50%;
          background: var(--vscode-charts-blue, var(--vscode-focusBorder));
        }
      }

      &.attention {
        font-weight: 600;

        &::after {
          background: var(--vscode-notificationsWarningIcon-foreground, var(--vscode-editorWarning-foreground));
        }
      }
    }
  }

  & > .plan-view {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 0.8rem 1.2rem 1.6rem;
    line-height: 1.5;
    max-width: 62rem;

    & h1 {
      font-size: 1.3em;
      margin: 0 0 0.6rem;
    }

    & h2 {
      font-size: 1.05em;
      margin: 1rem 0 0.3rem;
      border-bottom: 1px solid var(--vscode-panel-border);
    }

    & p,
    & ul,
    & ol {
      margin: 0.4rem 0;
    }

    /* A path or a symbol in a rule, a finding or a ruling: the file's backticks, set as code. */
    & code {
      font-family: var(--vscode-editor-font-family);
      background: var(--vscode-textCodeBlock-background);
      padding: 0 0.2em;
      border-radius: 3px;
      overflow-wrap: anywhere;
    }

    /* A fenced block is code the reader reads as code, not a path dropped into a sentence: no chip behind it. */
    & pre {
      background: transparent;
      padding: 0.5rem 0;
      overflow-x: auto;

      & code {
        background: none;
        padding: 0;
      }
    }

    & ul,
    & ol {
      list-style-position: outside;
      padding-left: 1.6em;
    }

    & li {
      margin: 0.45rem 0;
    }

    & .heading {
      font-size: 1.05em;
      margin: 0 0 0.5rem;
      padding-bottom: 0.2rem;
      border-bottom: 1px solid var(--vscode-panel-border);
    }

    & .goal {
      margin-top: 1rem;
    }

    & .note {
      opacity: 0.75;
      margin: 0.3rem 0;
    }

    /* A review round; the one still being written is boxed, since it is the reader's own draft. */
    & .round {
      margin: 0 0 1.2rem;

      &.pending {
        border: 1px solid var(--vscode-panel-border);
        border-radius: 4px;
        padding: 0.4rem 0.6rem;

        & .heading {
          margin-top: 0;
        }
      }

      & > .comments {
        margin-left: 0;
      }
    }

    & .comment .on {
      opacity: 0.75;
    }

    & .strike {
      margin: 0.25rem 0;
    }

    & .link.item {
      background: none;
      border: none;
      padding: 0;
      font: inherit;
      color: var(--vscode-textLink-foreground);
      cursor: pointer;

      &:hover {
        text-decoration: underline;
      }
    }

    & .problems {
      border: 1px solid var(--vscode-inputValidation-warningBorder);
      background: var(--vscode-inputValidation-warningBackground);
      border-radius: 4px;
      padding: 0.4rem 0.6rem;
      margin-bottom: 0.6rem;

      & .heading {
        margin-top: 0;
        border: none;
      }

      & .list {
        margin: 0.2rem 0;
        padding-left: 1.2em;
      }

      & .problem {
        margin: 0.15rem 0;
        font-family: var(--vscode-editor-font-family);      }
    }

    & .whole {
      padding: 0.25rem 0;
      border-bottom: 1px solid var(--vscode-panel-border);
    }

    & .prose p {
      margin: 0.3rem 0;
    }

    /* One scenario after another, set apart by space and a heading, not by boxes. */
    & .scenario,
    & .questions {
      margin: 1.6rem 0 0;

      & .intro {
        opacity: 0.75;
        margin-bottom: 0.4rem;
      }
    }

    & .rules,
    & .edges {
      list-style: none;
      padding: 0;
      margin: 0;
    }

    /* Edges sit under their rule, indented and a shade quieter; the indent is the relation. */
    & .edges {
      margin: 0.35rem 0 0 1.2em;
    }

    & .item {
      margin: 0 0 0.9rem;
      line-height: 1.55;

      &.edge {
        margin: 0 0 0.45rem;        opacity: 0.9;
      }

      /* The name is the lead-in, as it is in the file; the text follows it. */
      & .name {
        font-weight: 600;
      }

      /* Only the item's own text is struck; its comments and controls stay legible. */
      &.struck > .line > .text {
        text-decoration: line-through;
        opacity: 0.6;
      }

      &.applied > .line > .text,
      &.withdrawn > .line > .text {
        opacity: 0.7;
      }

      /* text | what the reader needs at a glance, aligned right. */
      & > .line {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: start;
        gap: 0 0.5rem;

        & > .text {
          min-width: 0;
        }
      }
    }

    & .aside {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      padding-top: 0.15em;
      white-space: nowrap;
    }

    & .citation {
      opacity: 0.6;
    }

    /* What is in order is a small mark; only a gap wears a badge. */
    & .chip {
      opacity: 0.55;
      font-family: var(--vscode-editor-font-family);

      &.proof {
        color: var(--vscode-testing-iconPassed);
        opacity: 0.9;
      }
    }

    & button.chip {
      background: none;
      border: none;
      padding: 0;
      cursor: pointer;
    }

    /* A decision reads top down: the finding, then the ruling; the label says whose line it is. */
    & .finding,
    & .ruling {
      display: flex;
      gap: 0.4rem;
      margin: 0.15rem 0 0.15rem 1rem;
      opacity: 0.9;

      & .kind {
        text-transform: uppercase;
        letter-spacing: 0.03em;
        opacity: 0.8;
        padding-top: 0.2em;
        white-space: nowrap;
      }

      & .text {
        flex: 1;
      }
    }

    & .ruling .kind {
      color: var(--vscode-testing-iconPassed);
      opacity: 1;
    }

    /* The wizard's head: where the reader stands among the pending decisions, and the way back and forward. */
    & .decisions > .wizard {
      display: flex;
      align-items: baseline;
      gap: 0.6rem;
      margin: 0 0 0.5rem;

      & .count {
        font-weight: 600;
      }

      & .left {
        flex: 1;        opacity: 0.75;
      }

      & .nav {
        display: inline-flex;
        gap: 0.3rem;

        & button {
          background: var(--vscode-button-secondaryBackground);
          color: var(--vscode-button-secondaryForeground);          padding: 0.1rem 0.5rem;

          &:hover:not(:disabled) {
            background: var(--vscode-button-secondaryHoverBackground);
          }

          &:disabled {
            opacity: 0.5;
            cursor: default;
          }
        }
      }
    }

    /*
     * A decision in play is a card: the question on top, then what the code
     * does and what was ruled as labelled paragraphs, and the ways to settle
     * it as buttons at the foot. The one waiting on the reader is marked at
     * its edge.
     */
    & .decisions > .decision {
      margin: 0 0 0.9rem;
      padding: 0.6rem 0.8rem;
      border: 1px solid var(--vscode-panel-border);
      border-left-width: 3px;
      border-radius: 4px;
      background: var(--vscode-editorWidget-background);

      &.attention {
        border-left-color: var(--vscode-editorWarning-foreground);
      }

      &.ruled {
        border-left-color: var(--vscode-testing-iconPassed);
      }

      & > .head {
        display: flex;
        align-items: baseline;
        gap: 0.5rem;
        flex-wrap: wrap;

        & .title {
          flex: 1;
          margin: 0;
          font-size: 1.05em;
          font-weight: 600;
        }
      }

      & > .on {
        opacity: 0.75;
        margin-bottom: 0.4rem;
      }

      & .finding,
      & .ruling,
      & .spec {
        flex-direction: column;
        gap: 0.1rem;
        margin: 0.5rem 0 0;

        & .kind {
          padding-top: 0;
        }
      }

      /*
       * The disagreement, both sides at once: the rules as the spec has them
       * and what the code does. Side by side where there is room, stacked
       * when there is not.
       */
      & .sides {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr));
        gap: 0.3rem 1.2rem;

        & .side {
          display: flex;
        }

        & .kind {
          text-transform: uppercase;
          letter-spacing: 0.03em;
          opacity: 0.8;
          white-space: nowrap;
        }

        & .rule {
          margin: 0 0 0.2rem;

          /* The name is a link, and a spec row's margin under it would space the rule's wrapped lines apart. */
          & .name {
            margin: 0;
            font-weight: 600;
          }
        }
      }

      /* Each way to settle the decision is one wide button: what kind of ruling it is, then the rule as it would read. */
      & .options {
        display: flex;
        flex-direction: column;
        gap: 0.4rem;
        margin: 0.7rem 0 0.1rem;

        & .heading {
          margin: 0;
          font-size: 1em;
          font-weight: 600;
        }

        & .lead {
          margin: 0 0 0.1rem;
          opacity: 0.75;
        }

        /* The planner's pick, under the options so every way is read before its argument. */
        & .recommendation {
          display: flex;
          gap: 0.4rem;
          margin: 0.5rem 0 0.1rem;

          & .kind {
            text-transform: uppercase;
            letter-spacing: 0.03em;
            white-space: nowrap;
            opacity: 0.8;
            color: var(--vscode-testing-iconPassed);
          }

          & .text {
            flex: 1;
          }
        }

        & .option {
          display: flex;
          gap: 0.6rem;
          align-items: baseline;
          text-align: left;
          padding: 0.4rem 0.6rem;
          border: 1px solid var(--vscode-panel-border);
          border-radius: 4px;
          background: var(--vscode-button-secondaryBackground);
          color: var(--vscode-button-secondaryForeground);

          &:hover {
            background: var(--vscode-button-secondaryHoverBackground);
          }

          /* What the recommendation beneath calls this option. */
          & .index {
            opacity: 0.8;
            font-variant-numeric: tabular-nums;
          }

          & .kind {
            text-transform: uppercase;
            letter-spacing: 0.03em;
            white-space: nowrap;
            opacity: 0.8;
          }

          /* Which rule this option rewrites; shown only when the decision is on more than one. */
          & .rule {
            font-weight: 600;
            white-space: nowrap;
          }

          & .text {
            flex: 1;
          }

          &.chosen {
            border-color: var(--vscode-testing-iconPassed);
            background: var(--vscode-button-background);
            color: var(--vscode-button-foreground);
          }
        }
      }
    }

    /* Settled decisions fold away: the finding and the ruling are the record, the title a footnote. */
    & .decisions > .history {
      margin-top: 0.6rem;

      & > summary {
        cursor: pointer;
        opacity: 0.75;      }

      & .decision.settled {
        margin: 0.6rem 0 0 0.4rem;
        padding: 0.3rem 0 0.3rem 0.6rem;
        border-left: 2px solid var(--vscode-panel-border);
        opacity: 0.8;
        & .finding,
        & .ruling {
          margin-left: 0;
        }

        & .foot {
          display: flex;
          gap: 0.6rem;
          margin-top: 0.2rem;          opacity: 0.7;
        }
      }
    }

    /*
     * Every act on a row wears the same small secondary button, so Comment,
     * Strike, Edit, Remove and Resolve read as one family.
     */
    & .line button,
    & .controls button,
    & .resolution button {
      background: var(--vscode-button-secondaryBackground);
      color: var(--vscode-button-secondaryForeground);      padding: 0.1rem 0.5rem;

      &:hover {
        background: var(--vscode-button-secondaryHoverBackground);
      }
    }

    & .controls {
      display: inline-flex;
      align-items: center;
      gap: 0.3rem;
      /* Out of sight until the pointer rests on the line, so the spec reads as prose; a row that needs an act shows them. */
      opacity: 0;
    }

    & .line:hover .controls,
    & .controls:focus-within,
    & .attention .controls {
      opacity: 1;
    }

    /* Lines outside the spec's items (the plan as a whole, comments) flow. */
    & .whole > .line,
    & .comment > .line {
      display: flex;
      align-items: baseline;
      flex-wrap: wrap;
      gap: 0.4rem;

      & > .text {
        flex: 1;
        min-width: 12em;
      }
    }

    /* Pending comments always show their Edit and Remove: they are the reader's own words, not the spec's. */
    & .comment .controls {
      opacity: 1;
    }

    & tr.attachments > td {
      border: none;
      padding-top: 0;
    }

    & .badge {
      opacity: 0.8;
      border: 1px solid var(--vscode-panel-border);
      border-radius: 3px;
      padding: 0 0.3rem;
      white-space: nowrap;

      /* A gap in coverage is the one thing that wears colour on a row. */
      &.gap {
        color: var(--vscode-editorWarning-foreground);
        border-color: var(--vscode-editorWarning-foreground);
      }

      &.state.applied,
      &.state.ruled {
        color: var(--vscode-testing-iconPassed);
        border-color: var(--vscode-testing-iconPassed);
      }

      &.state.open {
        color: var(--vscode-editorWarning-foreground);
        border-color: var(--vscode-editorWarning-foreground);
      }
    }

    & .link.file {
      background: none;
      border: none;
      padding: 0;
      font: inherit;
      color: var(--vscode-textLink-foreground);
      cursor: pointer;

      &:hover {
        text-decoration: underline;
      }
    }

    & .comments {
      list-style: none;
      margin: 0.2rem 0 0.2rem 1rem;
      padding: 0;
    }

    & .comment {
      margin: 0.25rem 0;
      border-left: 2px solid var(--vscode-focusBorder);
      padding-left: 0.5rem;

      &.closed {
        border-left-color: var(--vscode-testing-iconPassed);
        opacity: 0.8;
      }
    }

    & .resolution {
      display: flex;
      align-items: baseline;
      gap: 0.4rem;
      margin-top: 0.15rem;
      opacity: 0.9;

      & .kind {
        text-transform: uppercase;
        letter-spacing: 0.03em;
      }

      &.disagreed .kind {
        color: var(--vscode-editorWarning-foreground);
      }

      &.addressed .kind {
        color: var(--vscode-testing-iconPassed);
      }

      & .text {
        flex: 1;
      }
    }

    & .awaiting {
      color: var(--vscode-editorWarning-foreground, var(--vscode-charts-orange));
    }

    & .strikes {
      opacity: 0.85;
    }

    & .editor {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      gap: 0.3rem;
      margin: 0.3rem 0 0.3rem 1rem;

      & textarea {
        width: 100%;
        background: var(--vscode-input-background);
        color: var(--vscode-input-foreground);
        border: 1px solid var(--vscode-input-border, transparent);
        border-radius: 3px;
        padding: 0.3rem;
        font: inherit;
        resize: vertical;
      }
    }

    & .tasks {
      & .group > .heading {
        border: none;
        margin: 0.6rem 0 0.1rem;
        opacity: 0.85;
      }

      & .board {
        list-style: none;
        padding: 0;
        margin: 0;
      }

      & .task {
        padding: 0.25rem 0;
        border-bottom: 1px solid var(--vscode-panel-border);

        & .name {
          font-weight: 600;
        }

        &.removed .line > .text {
          text-decoration: line-through;
          opacity: 0.6;
        }

        &.tested .line > .text {
          opacity: 0.7;
        }
      }

      & .badge.state {
        &.in_progress {
          color: var(--vscode-charts-blue);
          border-color: var(--vscode-charts-blue);
        }

        &.done,
        &.tested {
          color: var(--vscode-testing-iconPassed);
          border-color: var(--vscode-testing-iconPassed);
        }

        &.blocked {
          color: var(--vscode-editorWarning-foreground);
          border-color: var(--vscode-editorWarning-foreground);
        }
      }

      & .paths {
        display: flex;
        gap: 0.4rem;
        margin-left: 1rem;

        & .kind {
          text-transform: uppercase;
          letter-spacing: 0.03em;
          opacity: 0.7;
          flex: 0 0 4rem;
        }
      }

      & .files,
      & .context {
        list-style: none;
        padding: 0;
        margin: 0.1rem 0 0;
        font-family: var(--vscode-editor-font-family);
      }

      & details.how {
        margin: 0.2rem 0 0.2rem 1rem;

        & > summary {
          cursor: pointer;
          text-transform: uppercase;
          letter-spacing: 0.03em;
          opacity: 0.7;
        }

        & > .body {
          opacity: 0.85;

          & ul {
            margin: 0.2rem 0;
            padding-left: 1.1rem;
          }
        }
      }

      & .verification {
        display: flex;
        gap: 0.4rem;
        & .kind {
          text-transform: uppercase;
          letter-spacing: 0.03em;        }

        &.ok .kind {
          color: var(--vscode-testing-iconPassed);
        }

        &.failed .kind {
          color: var(--vscode-errorForeground);
        }
      }

    }

    & .cleanup {
      & .toolbar {
        display: flex;
        gap: 0.6rem;
        align-items: center;

        & .count {
          opacity: 0.7;
        }
      }

      & .files {
        list-style: none;
        padding: 0;
        margin: 0.3rem 0;

        & .entry {
          margin: 0.3rem 0;

          & .pick {
            display: flex;
            gap: 0.4rem;
            align-items: center;

            & .link.file {
              font-family: var(--vscode-editor-font-family);
            }
          }
        }
      }

      & .units {
        list-style: none;
        padding: 0;
        margin: 0.1rem 0 0 1.6rem;

        & .unit {
          display: flex;
          gap: 0.5rem;
          align-items: baseline;

          & .link.file {
            font-family: var(--vscode-editor-font-family);
            opacity: 0.8;
          }
        }
      }

      & .choices {
        display: flex;
        gap: 0.4rem;
        align-items: center;
        flex-wrap: wrap;

        & .note {
          margin: 0;
        }
      }

      & .running {
        opacity: 0.85;
      }

      /* A split under way, unit by unit: the state reads as text, and colour only says done or not. */
      & .progress {
        & .headline {
          font-weight: 600;
          margin: 0.3rem 0;

          &.done {
            color: var(--vscode-testing-iconPassed);
          }

          &.failed {
            color: var(--vscode-editorWarning-foreground);
          }
        }

        & .activity {
          margin: 0;
          opacity: 0.7;
          font-family: var(--vscode-editor-font-family);
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        & .files .entry > .link.file {
          font-family: var(--vscode-editor-font-family);
        }

        & .unit {
          & .state {
            margin-left: auto;
            font-size: 0.9em;
          }

          &.waiting .state {
            opacity: 0.6;
          }

          &.within .state {
            color: var(--vscode-testing-iconPassed);
          }

          &.over .state {
            color: var(--vscode-editorWarning-foreground);
          }
        }

        & .split-into,
        & .moves {
          margin: 0.3rem 0;

          & .link.file {
            font-family: var(--vscode-editor-font-family);
            margin-right: 0.5rem;
          }
        }
      }
    }

  }

  & > .new-session {
    overflow-y: auto;
    padding: 0.8rem;

    & h2 {
      margin: 0 0 0.6rem;
      font-size: 1.1em;
    }

    /* The two pickers: what the session runs on is chosen here, not in a settings file. */
    & .models {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem 1rem;
      margin-bottom: 0.8rem;
      & label {
        display: flex;
        flex-direction: column;
        gap: 0.2rem;
      }
    }

    /* Work in the code on one tab, the upkeep of the intent on the other. */
    & .screens {
      display: flex;
      gap: 0.2rem;
      margin-bottom: 0.8rem;
      border-bottom: 1px solid var(--vscode-panel-border);

      & .tab {
        background: none;
        color: inherit;
        opacity: 0.7;
        border-bottom: 2px solid transparent;
        border-radius: 0;
        padding: 0.25rem 0.6rem;

        &:hover {
          opacity: 1;
          background: var(--vscode-list-hoverBackground);
        }

        &.active {
          opacity: 1;
          border-bottom-color: var(--vscode-focusBorder);
        }
      }

      /* How much waits to be filed: a count, not a call to action, so it stays neutral. */
      & .waiting {
        margin-left: 0.35rem;
        padding: 0 0.35rem;
        border: 1px solid var(--vscode-widget-border, var(--vscode-panel-border));
        border-radius: 999px;
        font-size: 0.85em;
      }
    }

    & .types {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
      gap: 0.5rem;
      margin-bottom: 0.8rem;
    }

    & .type {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      gap: 0.2rem;
      text-align: left;
      padding: 0.6rem;
      background: var(--vscode-input-background);
      color: var(--vscode-foreground);
      border: 1px solid var(--vscode-input-border, transparent);
      border-radius: 6px;

      &.selected {
        border-color: var(--vscode-focusBorder);
      }

      & .icon {
        font-size: 1.4em;
      }

      & .hint {
        opacity: 0.7;      }
    }

    & form {
      display: flex;
      flex-direction: column;
      gap: 0.6rem;

      & label {
        display: flex;
        flex-direction: column;
        gap: 0.2rem;      }

      & input,
      & textarea {
        background: var(--vscode-input-background);
        color: var(--vscode-input-foreground);
        border: 1px solid var(--vscode-input-border, transparent);
        border-radius: 3px;
        padding: 0.4rem;
      }

      & .hint {
        margin: 0;
        opacity: 0.7;      }

      & button[type='submit'] {
        align-self: flex-start;
      }

      /* Start the session, then what it should read: one line, the files after the button that links them. */
      & .submit {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.5rem;
      }
    }

    /* What can be picked up again: plans on disk, chats with no tab open, decisions waiting to be filed. */
    & .pick-up {
      margin-top: 1.2rem;
      border-top: 1px solid var(--vscode-panel-border);
      padding-top: 0.8rem;

      & h3 {
        margin: 0 0 0.4rem;
        font-size: 1em;
        opacity: 0.8;
      }

      & .picks {
        list-style: none;
        margin: 0;
        padding: 0;
        display: flex;
        flex-direction: column;
        gap: 0.1rem;
      }

      & .pick {
        width: 100%;
        display: flex;
        align-items: baseline;
        gap: 0.5rem;
        text-align: left;
        padding: 0.4rem 0.6rem;
        background: none;
        color: var(--vscode-foreground);
        border: none;
        border-radius: 4px;
        cursor: pointer;

        &:hover {
          background: var(--vscode-list-hoverBackground);
        }

        /* The name over what it says about itself, so a long chat title has the row to itself. */
        & .what {
          display: flex;
          flex-direction: column;
          gap: 0.1rem;
          min-width: 0;
        }

        & strong {
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }

        & .hint {
          opacity: 0.7;
        }

        &.approved .hint {
          color: var(--vscode-testing-iconPassed);
          opacity: 1;
        }
      }
    }
  }

  /*
   * One chat per phase, the picked one shown. A phase's runs scroll as one
   * column, each folded under its own name, so the conversations do not run
   * into each other; the build shows one task's at a time, named above it.
   */
  & > .chats {
    display: flex;
    flex-direction: column;

    & > .phase-chat {
      flex: 1;
      min-height: 0;
      display: flex;
      flex-direction: column;

      & > .empty {
        padding: 0.6rem;
        opacity: 0.7;
      }

      & > .run-switch {
        display: flex;
        flex-wrap: wrap;
        gap: 0.3rem;
        padding: 0.3rem 0.6rem;
        border-bottom: 1px solid var(--vscode-panel-border);

        & .task {
          &.selected {
            font-weight: 600;
            outline: 1px solid var(--vscode-focusBorder);
          }

          &.settled:not(.selected) {
            opacity: 0.7;
          }
        }
      }

      /* The switcher names the task above its conversation already. */
      &.task-chat .run-head {
        display: none;
      }
    }
  }

  & .runs {
    flex: 1;
    min-height: 0;
    overflow-y: auto;

    & > .run {
      & > .run-head {
        position: sticky;
        top: 0;
        z-index: 1;
        cursor: pointer;
        padding: 0.2rem 0.6rem;
        background: var(--vscode-editor-background);
        border-bottom: 1px solid var(--vscode-panel-border);
        text-transform: uppercase;
        letter-spacing: 0.03em;
        font-size: 0.9em;
        opacity: 0.7;
      }

      &.current > .run-head {
        opacity: 1;
      }

      /* What the user sends reaches the current run alone, so an earlier run cannot be resumed from here. */
      &:not(.current) .resume {
        display: none;
      }

      &.moved > .run-head::after {
        content: ' •';
        color: var(--vscode-charts-blue);
      }
    }

    /* One run and nothing to choose between: its header is noise. */
    & > .run:only-child > .run-head {
      display: none;
    }
  }

  & .transcript {
    padding: 0.6rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;

    & .status {
      margin: 0;
      opacity: 0.6;    }

    /*
     * The prompt is re-read as often as the reply, so it stays in the reading
     * flow at the left with an accent bar, not as a faint bubble stranded at
     * the right edge of a wide window.
     */
    & .user {
      align-self: stretch;
      background: var(--vscode-textBlockQuote-background, var(--vscode-input-background));
      border: 1px solid var(--vscode-input-border, transparent);
      border-left: 3px solid var(--vscode-textBlockQuote-border, var(--vscode-focusBorder));
      border-radius: 4px;
      padding: 0.4rem 0.6rem;
      white-space: pre-wrap;
      color: var(--vscode-foreground);
    }

    & .assistant {
      & .thinking {
        opacity: 0.5;        white-space: pre-wrap;
        max-height: 8rem;
        overflow-y: auto;
        margin: 0 0 0.3rem;
      }

      & .text {
        line-height: 1.45;

        & > :first-child {
          margin-top: 0;
        }

        & > :last-child {
          margin-bottom: 0;
        }

        & p,
        & ul,
        & ol {
          margin: 0.4rem 0;
        }

        & ul,
        & ol {
          list-style-position: outside;
          padding-left: 1.6em;
        }

        & li {
          margin: 0.45rem 0;
        }

        & code {
          font-family: var(--vscode-editor-font-family);          background: var(--vscode-textCodeBlock-background);
          padding: 0 0.2em;
          border-radius: 3px;
        }

        & pre {
          /* Colored code sits on the message like plain text does, not on a block of its own. */
          background: transparent;
          padding: 0.5rem 0;
          overflow-x: auto;

          & code {
            background: none;
            padding: 0;
          }
        }

        & pre.mermaid {
          background: none;
          text-align: center;

          & svg {
            max-width: 100%;
            height: auto;
          }

          &.failed {
            border-left: 2px solid var(--vscode-errorForeground);
            text-align: left;
            font-family: var(--vscode-editor-font-family);
            white-space: pre-wrap;
          }
        }

        & table {
          border-collapse: collapse;
          margin: 0.4rem 0;

          & th,
          & td {
            border: 1px solid var(--vscode-panel-border);
            padding: 0.2rem 0.5rem;
          }
        }

        & blockquote {
          margin: 0.4rem 0;
          padding-left: 0.6rem;
          border-left: 2px solid var(--vscode-panel-border);
          opacity: 0.85;
        }

        & a {
          color: var(--vscode-textLink-foreground);
        }
      }
    }

    & .tool {
      border-left: 2px solid var(--vscode-panel-border);
      padding-left: 0.5rem;
      &.failed {
        border-left-color: var(--vscode-errorForeground);
      }

      /* A finished step is plumbing: muting it leaves the conversation itself standing out. One that failed, or that is open to be read, stays at full strength. */
      &.done:not([open]):not(.failed) {
        opacity: 0.55;

        &:hover {
          opacity: 1;
        }
      }

      & summary {
        cursor: pointer;
        font-family: var(--vscode-editor-font-family);
        opacity: 0.85;
      }

      & .input,
      & .result {
        margin: 0.3rem 0;
        font-family: var(--vscode-editor-font-family);        white-space: pre-wrap;
        max-height: 20rem;
        overflow: auto;
        /* Colored code sits on the step like plain text does, not on a block of its own. */
        background: transparent;
      }

      & .result.error {
        color: var(--vscode-errorForeground);
      }

      &.edit-step {
        border-left-color: var(--vscode-gitDecoration-modifiedResourceForeground, var(--vscode-panel-border));

        & summary .stats {
          opacity: 0.7;
        }
      }
    }

    /* A file edit: the change it made, and the way to the rest of it. */
    & .edit {
      margin: 0.3rem 0;

      & .diff {
        margin: 0.3rem 0;
        font-family: var(--vscode-editor-font-family);        overflow-x: auto;
      }

      & .diff-line {
        display: block;
        white-space: pre;

        /* A colored line reads like the editor: the tinted background and the +/- mark carry the diff, not the text color. */
        & .code.hljs {
          color: var(--vscode-foreground);
        }
      }

      & .diff-line.add {
        color: var(--vscode-gitDecoration-addedResourceForeground, var(--vscode-charts-green));
        background: var(--vscode-diffEditor-insertedTextBackground, transparent);
      }

      & .diff-line.del {
        color: var(--vscode-gitDecoration-deletedResourceForeground, var(--vscode-charts-red));
        background: var(--vscode-diffEditor-removedTextBackground, transparent);
      }

      & .diff-line.hunk {
        opacity: 0.6;
      }

      & .edit-summary {
        margin: 0.2rem 0;
        opacity: 0.8;
      }

      /* A way out to the full edit, not part of it: kept small and out of the diff's reading line. */
      & .omitted {
        margin: 0.1rem 0;        text-align: right;
        opacity: 0.7;
      }
    }

    & .link {
      background: none;
      border: none;
      padding: 0;
      font: inherit;
      color: var(--vscode-textLink-foreground);
      cursor: pointer;
      text-align: left;

      &:hover {
        text-decoration: underline;
      }
    }

    & .permission {
      display: block;
      border: 1px solid var(--vscode-inputValidation-warningBorder);
      background: var(--vscode-inputValidation-warningBackground);
      border-radius: 6px;
      padding: 0.5rem 0.6rem;

      &.allowed {
        border-color: transparent;
        background: none;
        padding: 0 0.6rem;
      }

      & pre.command {
        margin: 0;
        font-family: var(--vscode-editor-font-family);        white-space: pre-wrap;
        background: transparent;
        opacity: 0.85;
      }

      & .input {
        font-family: var(--vscode-editor-font-family);        white-space: pre-wrap;
        max-height: 10rem;
        overflow: auto;
        margin: 0.3rem 0;
      }

      & .actions {
        display: flex;
        gap: 0.4rem;
      }

      /* A shell call: one row per command, its answer beside it and its buttons under it. */
      & .commands {
        list-style: none;
        margin: 0.3rem 0;
        padding: 0;

        & .command {
          display: flex;
          flex-wrap: wrap;
          align-items: center;
          gap: 0.4rem 0.8rem;
          padding: 0.2rem 0;

          & + .command {
            border-top: 1px solid var(--vscode-panel-border);
          }

          & code {
            flex: 1 1 12rem;
            font-family: var(--vscode-editor-font-family);            white-space: pre-wrap;
            word-break: break-all;
          }
        }

        /* Under the command at the left edge: on a wide window buttons trailing the command sit far from the eye and get missed. */
        & .line-actions {
          flex: 1 1 100%;
          display: flex;
          flex-wrap: wrap;
          gap: 0.4rem;
        }

        & .line-status {
          opacity: 0.8;

          &.denied {
            color: var(--vscode-errorForeground);
            opacity: 1;
          }
        }
      }

      & .deny-reason {
        display: block;
        box-sizing: border-box;
        width: 100%;
        margin-top: 0.4rem;
        background: var(--vscode-input-background);
        color: var(--vscode-input-foreground);
        border: 1px solid var(--vscode-input-border, transparent);
        border-radius: 3px;
        padding: 0.3rem 0.4rem;
      }

      & .decision {
        margin: 0.3rem 0 0;
        opacity: 0.8;
      }
    }

    & .question-card {
      display: block;
      border: 1px solid var(--vscode-focusBorder);
      border-radius: 6px;
      padding: 0.5rem 0.6rem;
      background: var(--vscode-editorWidget-background);

      & .question {
        display: block;
      }

      /* Only a resolved card lists its questions together; the form shows one at a time. */
      & :is(.answered, .asked) > .question {
        & + .question {
          margin-top: 0.8rem;
          border-top: 1px solid var(--vscode-panel-border);
          padding-top: 0.6rem;
        }
      }

      & .header {
        display: block;
      }

      & .ask {
        margin: 0.2rem 0 0.4rem;
        white-space: pre-wrap;
      }

      & .options {
        list-style: none;
        margin: 0;
        padding: 0;

        & li {
          margin: 0.2rem 0;
        }

        & label {
          display: flex;
          align-items: baseline;
          gap: 0.4rem;
        }

        & .explanation {
          display: block;
          margin-left: 1.4rem;
          opacity: 0.75;        }
      }

      & .other {
        display: block;
        margin-top: 0.5rem;
        & textarea {
          display: block;
          width: 100%;
          box-sizing: border-box;
          margin-top: 0.2rem;
          resize: vertical;
          font-family: inherit;
          background: var(--vscode-input-background);
          color: var(--vscode-input-foreground);
          border: 1px solid var(--vscode-input-border, transparent);
          border-radius: 3px;
          padding: 0.3rem;
        }
      }

      & .actions {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        margin-top: 0.6rem;
      }

      & .step,
      & .missing {
        opacity: 0.8;      }

      /* A resolved card: each question, and beneath it what was answered. */
      & .answer {
        margin: 0;
        white-space: pre-wrap;
        font-weight: 600;
      }

      & .unanswered {
        margin: 0.5rem 0 0;
        opacity: 0.8;        font-style: italic;
      }
    }

    & .turn {
      margin: 0;
      opacity: 0.6;      text-align: right;

      &.error {
        color: var(--vscode-errorForeground);
        opacity: 1;
      }
    }

    & .compaction {
      text-align: left;

      & > summary {
        cursor: pointer;
        text-align: right;
      }

      & .compaction-summary {
        margin-top: 0.25rem;
        opacity: 1;
        white-space: pre-wrap;
      }
    }

    & .error {
      color: var(--vscode-errorForeground);
      white-space: pre-wrap;

      & .resume {
        margin-left: 0.5rem;
      }
    }

    & .ended {
      opacity: 0.6;      font-style: italic;
    }

    & .working {
      margin: 0;
      opacity: 0.7;      animation: pulse 1.2s ease-in-out infinite;

      /* The turn is stalled on the user, not running: it reads as a warning, not as background progress. */
      &.needs-user {
        opacity: 1;
        font-weight: 600;
        color: var(--vscode-editorWarning-foreground, var(--vscode-charts-orange));
      }
    }

    /* Terminal output keeps its colours, in the theme's own terminal palette. */
    & .ansi-bold {
      font-weight: bold;
    }
    & .ansi-dim {
      opacity: 0.6;
    }
    & .ansi-italic {
      font-style: italic;
    }
    & .ansi-underline {
      text-decoration: underline;
    }
    & .ansi-strike {
      text-decoration: line-through;
    }
    /* A coloured background reads against the terminal's own foreground, not the theme's error red; an explicit foreground below still wins. */
    & [class*='ansi-bg-'] {
      color: var(--vscode-terminal-foreground);
    }
    & .ansi-fg-Black { color: var(--vscode-terminal-ansiBlack); }
    & .ansi-fg-Red { color: var(--vscode-terminal-ansiRed); }
    & .ansi-fg-Green { color: var(--vscode-terminal-ansiGreen); }
    & .ansi-fg-Yellow { color: var(--vscode-terminal-ansiYellow); }
    & .ansi-fg-Blue { color: var(--vscode-terminal-ansiBlue); }
    & .ansi-fg-Magenta { color: var(--vscode-terminal-ansiMagenta); }
    & .ansi-fg-Cyan { color: var(--vscode-terminal-ansiCyan); }
    & .ansi-fg-White { color: var(--vscode-terminal-ansiWhite); }
    & .ansi-fg-BrightBlack { color: var(--vscode-terminal-ansiBrightBlack); }
    & .ansi-fg-BrightRed { color: var(--vscode-terminal-ansiBrightRed); }
    & .ansi-fg-BrightGreen { color: var(--vscode-terminal-ansiBrightGreen); }
    & .ansi-fg-BrightYellow { color: var(--vscode-terminal-ansiBrightYellow); }
    & .ansi-fg-BrightBlue { color: var(--vscode-terminal-ansiBrightBlue); }
    & .ansi-fg-BrightMagenta { color: var(--vscode-terminal-ansiBrightMagenta); }
    & .ansi-fg-BrightCyan { color: var(--vscode-terminal-ansiBrightCyan); }
    & .ansi-fg-BrightWhite { color: var(--vscode-terminal-ansiBrightWhite); }
    & .ansi-bg-Black { background: var(--vscode-terminal-ansiBlack); }
    & .ansi-bg-Red { background: var(--vscode-terminal-ansiRed); }
    & .ansi-bg-Green { background: var(--vscode-terminal-ansiGreen); }
    & .ansi-bg-Yellow { background: var(--vscode-terminal-ansiYellow); }
    & .ansi-bg-Blue { background: var(--vscode-terminal-ansiBlue); }
    & .ansi-bg-Magenta { background: var(--vscode-terminal-ansiMagenta); }
    & .ansi-bg-Cyan { background: var(--vscode-terminal-ansiCyan); }
    & .ansi-bg-White { background: var(--vscode-terminal-ansiWhite); }
    & .ansi-bg-BrightBlack { background: var(--vscode-terminal-ansiBrightBlack); }
    & .ansi-bg-BrightRed { background: var(--vscode-terminal-ansiBrightRed); }
    & .ansi-bg-BrightGreen { background: var(--vscode-terminal-ansiBrightGreen); }
    & .ansi-bg-BrightYellow { background: var(--vscode-terminal-ansiBrightYellow); }
    & .ansi-bg-BrightBlue { background: var(--vscode-terminal-ansiBrightBlue); }
    & .ansi-bg-BrightMagenta { background: var(--vscode-terminal-ansiBrightMagenta); }
    & .ansi-bg-BrightCyan { background: var(--vscode-terminal-ansiBrightCyan); }
    & .ansi-bg-BrightWhite { background: var(--vscode-terminal-ansiBrightWhite); }
  }

  & > .composer {
    border-top: 1px solid var(--vscode-panel-border);
    padding: 0.4rem;

    & form {
      display: flex;
      flex-direction: column;
      gap: 0.3rem;
    }

    /* Who what is typed reaches, so a tab with several conversations never leaves it to a guess. */
    & .recipient,
    & .refusal {
      margin: 0;
      font-size: 0.9em;
    }

    & .recipient {
      opacity: 0.8;
    }

    & .refusal {
      color: var(--vscode-editorWarning-foreground);
    }

    & textarea {
      width: 100%;
      box-sizing: border-box;
      resize: vertical;
      background: var(--vscode-input-background);
      color: var(--vscode-input-foreground);
      border: 1px solid var(--vscode-input-border, transparent);
      border-radius: 3px;
      padding: 0.4rem;
    }

    & .actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      align-items: center;
      gap: 0.4rem;

      & .switches {
        margin-right: auto;
        display: flex;
        align-items: center;
        gap: 0.8rem;
        min-width: 0;        opacity: 0.85;

        & label {
          cursor: pointer;
        }
      }

      & .context {
        display: inline-flex;
        align-items: center;
        gap: 0.3rem;

        & .left {
          color: var(--vscode-descriptionForeground);

          &.low {
            color: var(--vscode-editorWarning-foreground, var(--vscode-errorForeground));
          }
        }

        & .compact {
          display: inline-flex;
          align-items: center;
          padding: 0.25rem 0.4rem;
        }
      }
    }

    & .mcp-servers {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;      opacity: 0.85;

      & .server {
        display: inline-flex;
        align-items: center;
        gap: 0.3rem;
        color: var(--vscode-descriptionForeground);

        &.failed,
        &.needs-auth {
          color: var(--vscode-errorForeground);
        }

        & .reconnect {
          background: none;
          color: inherit;
          padding: 0 0.2rem;
          line-height: 1;
        }
      }
    }
  }
}

/* The linked files beside the button that links them: the composer's and the new-session card's. */
linked-files-row {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  /* A flex item may be given less than its content; the chips wrap among themselves rather than under the button. */
  min-width: 0;
  & .link-file {
    flex: none;
    padding: 0.2rem 0.5rem;
  }

  & .files {
