      &:hover {
        background: none;
        opacity: 1;
      }
    }
  }
}

/*
 * A form control does not inherit the page font. Left alone it renders in the browser's own family and
 * size, which is below the floor the root sets and beside text that follows it.
 */
button,
select,
input,
textarea {
  font-family: inherit;
  font-size: inherit;
}

button {
  background: var(--vscode-button-background);
