    if (!pending) return
    this.pendingModelSwitch.delete(run.id)
    await this.sessions.setProfile(run.id, pending)
  }

  /** Whether the view shows the session, its own tab or its feature's. */
  isOpen(sessionId: string): boolean {
    const record = this.sessions.get(sessionId)
    return record !== undefined && this.panelOf(this.tabIdOf(record)) !== undefined
  }

  /** A session's status, or its running check's: the check has no tab, so its state shows on the plan's. */
  statusOf(sessionId: string): SessionStatus {
    const child = this.sessions.liveChildOf(sessionId)
    return this.statuses.get(child?.id ?? sessionId) ?? 'idle'
  }

  private panelOf(tabId: string): ChatView | undefined {
    return this.surface?.tabId === tabId ? this.surface : undefined
  }

  /**
   * VS Code resolved the view: on first show, or again after a window reload,
   * when its state names the session it showed. A session removed meanwhile
   * leaves the view on the new-session screen rather than empty.
   */
  resolveWebviewView(view: vscode.WebviewView, context: vscode.WebviewViewResolveContext<{ tabId?: string }>): void {
    const asked = this.pendingTab
    this.pendingTab = undefined
    const tabId = asked ? asked.tabId : context.state?.tabId
