    // The Sessions view marks the session being looked at, which changes as the view is shown and hidden.
    view.onDidChangeVisibility(() => this.changed.fire())
    this.changed.fire()
  }

  /** The new-session screen in the view. */
  showNewSession(): void {
    this.show(undefined)
    // The plan list is read fresh, so a spec written since the last state is offered.
    void this.sendState()
  }

  /** Puts the tab in the view and brings the view up; one the sidebar has not resolved yet opens on it. */
  private show(tabId: string | undefined): void {
