    else await this.newSession('plan', feature, resumePlanPrompt(feature))
  }

  async open(sessionId: string): Promise<void> {
    const record = this.sessions.get(sessionId)
    if (record) await this.reveal(record)
  }

  /** Stopping a session stops the feature it stands for: every run under it, not the one it is keyed by. The view leaves its tab with it. */
  async close(sessionId: string): Promise<void> {
